1; % OctaLink standalone script: GNU Octave 7+; all integration executes here.
% Generated from the validated detached model; no Python required.

function y = ol_scalar(x)
  if numel(x) ~= 1 || ~isreal(x) || ~isfinite(x)
    error('OctaLink: expected one finite real scalar; use Demux for vectors');
  endif
  y = double(x);
endfunction
function y = ol_power(a,b)
  if abs(b) > 1024, error('OctaLink: exponent magnitude exceeds 1024'); endif
  y = ol_scalar(a^b);
endfunction
function y = ol_mod(a,b)
  if b == 0, error('OctaLink: division by zero'); endif
  y = mod(a,b);
endfunction
function ol_finite(x)
  if ~isreal(x) || any(~isfinite(x(:)))
    error('OctaLink: non-finite or complex signal/state; reduce dt or check model');
  endif
endfunction

function [v,dx,z] = ol_evaluate(t,x,z,update,hits,left_step)
v = cell(6,1); dx = zeros(1,1);
if t >= 1, v{1}=1; else v{1}=0; endif
ol_finite(v{1});
v{4} = x(1:1);
ol_finite(v{4});
v{2} = 0+ol_scalar(v{1})-ol_scalar(v{4});
ol_finite(v{2});
v{5} = [reshape(v{1},1,[]),reshape(v{4},1,[])];
ol_finite(v{5});
v{3} = 2*ol_scalar(v{2});
ol_finite(v{3});
v{6} = reshape(v{5},1,[]);
ol_finite(v{6});
dx(1:1) = ol_scalar(v{3});
ol_finite(dx);
endfunction
